# Independent check #1: union-find over open cells
rows=[l for l in open('maze.orig.txt').read().splitlines()]
R,C=len(rows),len(rows[0])
parent={}
def find(x):
    while parent[x]!=x:
        parent[x]=parent[parent[x]]; x=parent[x]
    return x
def union(a,b):
    ra,rb=find(a),find(b)
    if ra!=rb: parent[ra]=rb
open_cells=[]
for r in range(R):
    for c in range(C):
        if rows[r][c]!='#':
            parent[(r,c)]=(r,c); open_cells.append((r,c))
for r,c in open_cells:
    for dr,dc in ((1,0),(0,1)):
        n=(r+dr,c+dc)
        if 0<=n[0]<R and 0<=n[1]<C and rows[n[0]][n[1]]!='#':
            union((r,c),n)
groups={}
for cell in open_cells:
    groups.setdefault(find(cell),[]).append(cell)
print("open cells:",len(open_cells),"components:",len(groups))
for k,v in groups.items():
    print(" size",len(v),"contains_start",(1,1) in v,"contains_exit",(23,23) in v)
