# Check #4: Dijkstra (heapq) shortest path search from @ to E
import heapq
rows=[l for l in open('maze.orig.txt').read().splitlines()]
start=next((i,j) for i,r in enumerate(rows) for j,ch in enumerate(r) if ch=="@")
goal=next((i,j) for i,r in enumerate(rows) for j,ch in enumerate(r) if ch=="E")
dist={start:0}; pq=[(0,start)]; prev={}
while pq:
    d,(r,c)=heapq.heappop(pq)
    if (r,c)==goal: break
    if d>dist.get((r,c),1e9): continue
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        n=(r+dr,c+dc)
        if 0<=n[0]<len(rows) and 0<=n[1]<len(rows[0]) and rows[n[0]][n[1]]!="#":
            if d+1<dist.get(n,1e9):
                dist[n]=d+1; prev[n]=(r,c); heapq.heappush(pq,(d+1,n))
print("Dijkstra: exit reachable:", goal in dist, "| cells settled:", len(dist))
if goal in dist:
    print("path length:", dist[goal])

# Structural invariant: move.py only ever turns '@'->'.' and a floor cell->'@'.
# It never converts a '#' to '.', so the set of walls can never change.
print("\nInvariant: walls are immutable under move.py -> components can never merge.")
