# Fresh, independent verification: simple stack-based DFS, no reuse of earlier code
grid = open('maze.txt').read().splitlines()
H, W = len(grid), len(grid[0])
assert all(len(r) == W for r in grid), "ragged grid"

start = exit_ = None
for i in range(H):
    for j in range(W):
        if grid[i][j] == '@': start = (i, j)
        if grid[i][j] == 'E': exit_ = (i, j)
print('start =', start, ' exit =', exit_, ' grid =', H, 'x', W)

stack, seen = [start], {start}
while stack:                      # iterative DFS
    i, j = stack.pop()
    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
        p = (i+di, j+dj)
        if 0 <= p[0] < H and 0 <= p[1] < W and grid[p[0]][p[1]] != '#' and p not in seen:
            seen.add(p); stack.append(p)

print('reachable squares from @:', len(seen))
print('exit reachable?', exit_ in seen)

# The wall frontier: every wall touching a reachable square, and what lies beyond it
frontier = {}
for (i, j) in seen:
    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
        p = (i+di, j+dj)
        if not (0 <= p[0] < H and 0 <= p[1] < W): continue
        if grid[p[0]][p[1]] == '#':
            beyond = [(p[0]+a, p[1]+b) for a, b in ((1,0),(-1,0),(0,1),(0,-1))
                      if 0 <= p[0]+a < H and 0 <= p[1]+b < W and grid[p[0]+a][p[1]+b] not in '#']
            frontier[p] = beyond
print('frontier walls bordering the @-region:', len(frontier))
print('every neighbour beyond the frontier is floor of the OTHER component:',
      all(grid[a][b] in '.E' and (a, b) not in seen for v in frontier.values() for a, b in v))
