from collections import deque
rows = [list(l) for l in open('maze.txt').read().splitlines()]
start = next((i,j) for i,r in enumerate(rows) for j,ch in enumerate(r) if ch=='@')
# BFS to get region
seen={start}; q=deque([start]); prev={}
while q:
    r,c=q.popleft()
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        n=(r+dr,c+dc)
        if 0<=n[0]<len(rows) and 0<=n[1]<len(rows[n[0]]) and rows[n[0]][n[1]]!='#' and n not in seen:
            seen.add(n); prev[n]=(r,c); q.append(n)
print("region size", len(seen), "start", start)
# DFS traversal visiting all cells, with backtracking; returns to start at end
DIRS={'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
INV={(v,k) for k,v in DIRS.items()}
INV={v:k for k,v in DIRS.items()}
visited={start}
moves=[]
cur=start
def neighbors(p):
    r,c=p
    out=[]
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        n=(r+dr,c+dc)
        if n in seen: out.append(n)
    return out
# iterative DFS with stack of (node, iterator)
sys_stack=[(start, iter(neighbors(start)))]
path=[start]
while sys_stack:
    node, it = sys_stack[-1]
    advanced=False
    for nxt in it:
        if nxt not in visited:
            visited.add(nxt)
            moves.append(INV[(nxt[0]-node[0], nxt[1]-node[1])])
            path.append(nxt)
            sys_stack.append((nxt, iter(neighbors(nxt))))
            advanced=True
            break
    if not advanced:
        sys_stack.pop()
        if len(path)>1:
            back=path.pop()
            par=path[-1]
            moves.append(INV[(par[0]-back[0], par[1]-back[1])])
print("visited all:", len(visited)==len(seen), "moves:", len(moves))
print(' '.join(moves))
