{"command":"cat > pathgen.py <<'EOF'
from collections import deque
import sys
rows = [list(l) for l in open("maze.txt").read().splitlines()]
R = len(rows)
STEPS = {"up": (-1, 0), "down": (1, 0), "left": (0, -1), "right": (0, 1)}
def find(ch):
    return next((i, j) for i, r in enumerate(rows) for j, c in enumerate(r) if c == ch)
def path(src, dst):
    prev = {src: None}; q = deque([src])
    while q:
        cur = q.popleft()
        if cur == dst: break
        r, c = cur
        for d, (dr, dc) in STEPS.items():
            n = (r+dr, c+dc)
            if 0 <= n[0] < R and 0 <= n[1] < len(rows[n[0]]) and rows[n[0]][n[1]] != "#" and n not in prev:
                prev[n] = (cur, d); q.append(n)
    if dst not in prev: return None
    out = []; cur = dst
    while prev[cur] is not None:
        p, d = prev[cur]; out.append(d); cur = p
    return list(reversed(out))
if __name__ == "__main__":
    a = tuple(map(int, sys.argv[1:3])); b = tuple(map(int, sys.argv[3:5]))
    p = path(a, b)
    print(" ".join(p) if p else "NO PATH")
