rows = [list(l) for l in open("maze.txt").read().splitlines()]
R = len(rows)
STEPS = {"up": (-1,0), "down": (1,0), "left": (0,-1), "right": (0,1)}
def find(ch):
    return next((i,j) for i,r in enumerate(rows) for j,c in enumerate(r) if c==ch)
pos = find("@"); ex = find("E")
visited = {pos}
random.seed(12345)
for step in range(5_000_000):
    d = random.choice("UDLR")
    dr,dc = {"U":(-1,0),"D":(1,0),"L":(0,-1),"R":(0,1)}[d]
