        pos = (nr,nc); visited.add(pos)
    if pos == ex:
        print("REACHED EXIT at step", step); break
else:
    print("random walk finished; exit never reached")
print("distinct cells visited:", len(visited))
print("exit in visited set:", ex in visited)
print("max row visited:", max(v[0] for v in visited), " max col visited:", max(v[1] for v in visited))
