{"command":"python3 - <<'EOF'
# Build a walk that visits every dead end of the start region and returns,
# using the PRISTINE maze layout (walls never change during movement).
grid=open('maze.txt').read().split('\n')
R=C=29
def pos_of(g): return next((i,j) for i,row in enumerate(g) for j,ch in enumerate(row) if ch=='@')
start=pos_of(grid)
DIR={(-1,0):'up',(1,0):'down',(0,-1):'left',(0,1):'right'}
OPP={'up':'down','down':'up','left':'right','right':'left'}
def nbrs(p):
    return [(p[0]+di,p[1]+dj) for di,dj in ((-1,0),(1,0),(0,-1),(0,1))
            if 0<=p[0]+di<R and 0<=p[1]+dj<C and grid[p[0]+di][p[1]+dj]!='#']
seen={start}; moves=[]
def dfs(p):
    for n in nbrs(p):
        if n in seen: continue
        seen.add(n)
        d=DIR[(n[0]-p[0],n[1]-p[1])]
        moves.append(d)
        dfs(n)
        moves.append(OPP[d])
dfs(start)
print("squares visited:",len(seen),"| moves:",len(moves))
open('walk.txt','w').write('\n'.join(moves)+'\n')
EOF"}

