# Final independent confirmation: exhaustive flood fill of every open cell,
# grouping by connected component, then reporting where @ and E sit.
rows = open('maze.txt').read().splitlines()
R, C = len(rows), len(rows[0])
seen = set()
comps = []
for r in range(R):
    for c in range(C):
        if rows[r][c] != '#' and (r, c) not in seen:
            comp, stack = set(), [(r, c)]
            seen.add((r, c))
            while stack:
                cr, cc = stack.pop()
                comp.add((cr, cc))
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < R and 0 <= nc < C and rows[nr][nc] != '#' and (nr,nc) not in seen:
                        seen.add((nr, nc)); stack.append((nr, nc))
            comps.append(comp)
loc = {ch: (r, c) for r in range(R) for c in range(C) for ch in [rows[r][c]] if ch in '@E'}
