DIRS={'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
def route(a,b):
    q=deque([a]); prev={a:None}
    while q:
        cur=q.popleft()
        if cur==b: break
        r,c=cur
        for d,(dr,dc) in DIRS.items():
            n=(r+dr,c+dc)
            if 0<=n[0]<H and 0<=n[1]<W and rows[n[0]][n[1]]!='#' and n not in prev:
